-- ============================================================================
-- Aprobacion de Graneles: carga inicial de especificaciones
-- ============================================================================
--
-- 73 graneles y 508 parametros, parseados de 30 documentos ESP-DOM / ESP-COS /
-- ESP-LCC. Es la misma base que la app standalone traia escrita adentro del
-- archivo. Reglas que se aplicaron al parsear (resumen-proyecto-graneles.md):
--
--   * El codigo G es el identificador. Excepcion: M030017, alcohol etilico
--     neutro, que se envasa tal cual y funciona como granel.
--   * Sin microbiologia, fugas, peso ni torque: son controles de producto
--     terminado o de envase, no de liberacion del granel.
--   * Cristal Citrico usa el rango de Liberacion, no el Deseado.
--   * Densidad de valor unico sin tolerancia: queda como objetivo, sin rango.
--
-- El JSON va tal cual salio del parseo y se desarma aca, en vez de escribir 73
-- INSERT a mano: asi el archivo se puede comparar contra el original.
--
-- Los parametros reciben id <codigo>-<n> segun su orden en la ficha. Es estable
-- entre despliegues, y los resultados de las muestras se enlazan por ese id.
--
-- ON CONFLICT DO NOTHING: si alguien ya creo un granel desde la app antes de
-- que corra esta migracion, se respeta el suyo.

INSERT INTO gra_especificaciones
    (id, code, name, category, brand, doc_ref, doc_version, parametros, datos, actualizado_por)
SELECT
    'spec-' || lower(s->>'code'),
    s->>'code',
    s->>'name',
    nullif(s->>'category', ''),
    nullif(s->>'brand', ''),
    nullif(s->>'docRef', ''),
    nullif(s->>'docVersion', ''),
    coalesce(
        (SELECT jsonb_agg(p || jsonb_build_object('id', (s->>'code') || '-' || n) ORDER BY n)
         FROM jsonb_array_elements(s->'parameters') WITH ORDINALITY AS t(p, n)),
        '[]'::jsonb),
    s - 'code' - 'name' - 'category' - 'brand' - 'docRef' - 'docVersion' - 'parameters',
    'carga inicial'
FROM jsonb_array_elements($seed$
